class Product extends DataClass implements Insertable<Product> {
  final String id;
  final String code;
  final String name;
  final String nameNormalized;

  /// SPEC §13 katsayısı, ×10.000 (1,00 → 10000).
  final Rate priceCoefficient;

  /// Satış ve stok birimi. Sünger `M3`; ince malzeme (çivi, yapıştırıcı,
  /// zikzak yay) ADET/KG/KUTU/LITRE/METRE (D-22).
  ///
  /// Birim ürün kartında sabittir: geçmiş hareketlerin birimi değişirse
  /// maliyet anlamını yitirir.
  final String unit;
  final String? dns;
  final String? foamType;
  final Dimension? defaultWidth;
  final Dimension? defaultHeight;

  /// JSON dizi, ör. `[5,8,10]` (SPEC §1 "standart kalınlıklar").
  final String? standardThicknesses;
  final UnitPrice? defaultSalePriceM3;
  final int criticalStockPieces;
  final Volume? minStockVolume;
  final bool isActive;
  final String? note;
  const Product({
    required this.id,
    required this.code,
    required this.name,
    required this.nameNormalized,
    required this.priceCoefficient,
    required this.unit,
    this.dns,
    this.foamType,
    this.defaultWidth,
    this.defaultHeight,
    this.standardThicknesses,
    this.defaultSalePriceM3,
    required this.criticalStockPieces,
    this.minStockVolume,
    required this.isActive,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['code'] = Variable<String>(code);
    map['name'] = Variable<String>(name);
    map['name_normalized'] = Variable<String>(nameNormalized);
    {
      map['price_coefficient'] = Variable<int>(
        $ProductsTable.$converterpriceCoefficient.toSql(priceCoefficient),
      );
    }
    map['unit'] = Variable<String>(unit);
    if (!nullToAbsent || dns != null) {
      map['dns'] = Variable<String>(dns);
    }
    if (!nullToAbsent || foamType != null) {
      map['foam_type'] = Variable<String>(foamType);
    }
    if (!nullToAbsent || defaultWidth != null) {
      map['default_width'] = Variable<int>(
        $ProductsTable.$converterdefaultWidthn.toSql(defaultWidth),
      );
    }
    if (!nullToAbsent || defaultHeight != null) {
      map['default_height'] = Variable<int>(
        $ProductsTable.$converterdefaultHeightn.toSql(defaultHeight),
      );
    }
    if (!nullToAbsent || standardThicknesses != null) {
      map['standard_thicknesses'] = Variable<String>(standardThicknesses);
    }
    if (!nullToAbsent || defaultSalePriceM3 != null) {
      map['default_sale_price_m3'] = Variable<int>(
        $ProductsTable.$converterdefaultSalePriceM3n.toSql(defaultSalePriceM3),
      );
    }
    map['critical_stock_pieces'] = Variable<int>(criticalStockPieces);
    if (!nullToAbsent || minStockVolume != null) {
      map['min_stock_volume'] = Variable<int>(
        $ProductsTable.$converterminStockVolumen.toSql(minStockVolume),
      );
    }
    map['is_active'] = Variable<bool>(isActive);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      code: Value(code),
      name: Value(name),
      nameNormalized: Value(nameNormalized),
      priceCoefficient: Value(priceCoefficient),
      unit: Value(unit),
      dns: dns == null && nullToAbsent ? const Value.absent() : Value(dns),
      foamType: foamType == null && nullToAbsent
          ? const Value.absent()
          : Value(foamType),
      defaultWidth: defaultWidth == null && nullToAbsent
          ? const Value.absent()
          : Value(defaultWidth),
      defaultHeight: defaultHeight == null && nullToAbsent
          ? const Value.absent()
          : Value(defaultHeight),
      standardThicknesses: standardThicknesses == null && nullToAbsent
          ? const Value.absent()
          : Value(standardThicknesses),
      defaultSalePriceM3: defaultSalePriceM3 == null && nullToAbsent
          ? const Value.absent()
          : Value(defaultSalePriceM3),
      criticalStockPieces: Value(criticalStockPieces),
      minStockVolume: minStockVolume == null && nullToAbsent
          ? const Value.absent()
          : Value(minStockVolume),
      isActive: Value(isActive),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
    );
  }

  factory Product.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Product(
      id: serializer.fromJson<String>(json['id']),
      code: serializer.fromJson<String>(json['code']),
      name: serializer.fromJson<String>(json['name']),
      nameNormalized: serializer.fromJson<String>(json['nameNormalized']),
      priceCoefficient: serializer.fromJson<Rate>(json['priceCoefficient']),
      unit: serializer.fromJson<String>(json['unit']),
      dns: serializer.fromJson<String?>(json['dns']),
      foamType: serializer.fromJson<String?>(json['foamType']),
      defaultWidth: serializer.fromJson<Dimension?>(json['defaultWidth']),
      defaultHeight: serializer.fromJson<Dimension?>(json['defaultHeight']),
      standardThicknesses: serializer.fromJson<String?>(
        json['standardThicknesses'],
      ),
      defaultSalePriceM3: serializer.fromJson<UnitPrice?>(
        json['defaultSalePriceM3'],
      ),
      criticalStockPieces: serializer.fromJson<int>(
        json['criticalStockPieces'],
      ),
      minStockVolume: serializer.fromJson<Volume?>(json['minStockVolume']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      note: serializer.fromJson<String?>(json['note']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'code': serializer.toJson<String>(code),
      'name': serializer.toJson<String>(name),
      'nameNormalized': serializer.toJson<String>(nameNormalized),
      'priceCoefficient': serializer.toJson<Rate>(priceCoefficient),
      'unit': serializer.toJson<String>(unit),
      'dns': serializer.toJson<String?>(dns),
      'foamType': serializer.toJson<String?>(foamType),
      'defaultWidth': serializer.toJson<Dimension?>(defaultWidth),
      'defaultHeight': serializer.toJson<Dimension?>(defaultHeight),
      'standardThicknesses': serializer.toJson<String?>(standardThicknesses),
      'defaultSalePriceM3': serializer.toJson<UnitPrice?>(defaultSalePriceM3),
      'criticalStockPieces': serializer.toJson<int>(criticalStockPieces),
      'minStockVolume': serializer.toJson<Volume?>(minStockVolume),
      'isActive': serializer.toJson<bool>(isActive),
      'note': serializer.toJson<String?>(note),
    };
  }

  Product copyWith({
    String? id,
    String? code,
    String? name,
    String? nameNormalized,
    Rate? priceCoefficient,
    String? unit,
    Value<String?> dns = const Value.absent(),
    Value<String?> foamType = const Value.absent(),
    Value<Dimension?> defaultWidth = const Value.absent(),
    Value<Dimension?> defaultHeight = const Value.absent(),
    Value<String?> standardThicknesses = const Value.absent(),
    Value<UnitPrice?> defaultSalePriceM3 = const Value.absent(),
    int? criticalStockPieces,
    Value<Volume?> minStockVolume = const Value.absent(),
    bool? isActive,
    Value<String?> note = const Value.absent(),
  }) => Product(
    id: id ?? this.id,
    code: code ?? this.code,
    name: name ?? this.name,
    nameNormalized: nameNormalized ?? this.nameNormalized,
    priceCoefficient: priceCoefficient ?? this.priceCoefficient,
    unit: unit ?? this.unit,
    dns: dns.present ? dns.value : this.dns,
    foamType: foamType.present ? foamType.value : this.foamType,
    defaultWidth: defaultWidth.present ? defaultWidth.value : this.defaultWidth,
    defaultHeight: defaultHeight.present
        ? defaultHeight.value
        : this.defaultHeight,
    standardThicknesses: standardThicknesses.present
        ? standardThicknesses.value
        : this.standardThicknesses,
    defaultSalePriceM3: defaultSalePriceM3.present
        ? defaultSalePriceM3.value
        : this.defaultSalePriceM3,
    criticalStockPieces: criticalStockPieces ?? this.criticalStockPieces,
    minStockVolume: minStockVolume.present
        ? minStockVolume.value
        : this.minStockVolume,
    isActive: isActive ?? this.isActive,
    note: note.present ? note.value : this.note,
  );
  Product copyWithCompanion(ProductsCompanion data) {
    return Product(
      id: data.id.present ? data.id.value : this.id,
      code: data.code.present ? data.code.value : this.code,
      name: data.name.present ? data.name.value : this.name,
      nameNormalized: data.nameNormalized.present
          ? data.nameNormalized.value
          : this.nameNormalized,
      priceCoefficient: data.priceCoefficient.present
          ? data.priceCoefficient.value
          : this.priceCoefficient,
      unit: data.unit.present ? data.unit.value : this.unit,
      dns: data.dns.present ? data.dns.value : this.dns,
      foamType: data.foamType.present ? data.foamType.value : this.foamType,
      defaultWidth: data.defaultWidth.present
          ? data.defaultWidth.value
          : this.defaultWidth,
      defaultHeight: data.defaultHeight.present
          ? data.defaultHeight.value
          : this.defaultHeight,
      standardThicknesses: data.standardThicknesses.present
          ? data.standardThicknesses.value
          : this.standardThicknesses,
      defaultSalePriceM3: data.defaultSalePriceM3.present
          ? data.defaultSalePriceM3.value
          : this.defaultSalePriceM3,
      criticalStockPieces: data.criticalStockPieces.present
          ? data.criticalStockPieces.value
          : this.criticalStockPieces,
      minStockVolume: data.minStockVolume.present
          ? data.minStockVolume.value
          : this.minStockVolume,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      note: data.note.present ? data.note.value : this.note,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Product(')
          ..write('id: $id, ')
          ..write('code: $code, ')
          ..write('name: $name, ')
          ..write('nameNormalized: $nameNormalized, ')
          ..write('priceCoefficient: $priceCoefficient, ')
          ..write('unit: $unit, ')
          ..write('dns: $dns, ')
          ..write('foamType: $foamType, ')
          ..write('defaultWidth: $defaultWidth, ')
