          ..write('standardThicknesses: $standardThicknesses, ')
          ..write('defaultSalePriceM3: $defaultSalePriceM3, ')
          ..write('criticalStockPieces: $criticalStockPieces, ')
          ..write('minStockVolume: $minStockVolume, ')
          ..write('isActive: $isActive, ')
          ..write('note: $note')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    code,
    name,
