class Customer extends DataClass implements Insertable<Customer> {
  final String id;
  final String code;
  final String title;
  final String titleNormalized;

  /// SPEC §9 "Yetkili".
  final String? contactPerson;
  final String? phone;
  final String? email;
  final String? address;
  final String? taxOffice;
  final String? taxNumber;

  /// null ise Ayarlar'daki varsayılan kullanılır (BRIEF §3.4).
  final String? defaultPriceMode;
  final Rate defaultDiscountRate;

  /// 0 = limitsiz (BRIEF §5).
  final Money riskLimit;
  final int paymentTermDays;
  final bool isActive;
  final String? note;
  const Customer({
    required this.id,
    required this.code,
    required this.title,
    required this.titleNormalized,
    this.contactPerson,
    this.phone,
    this.email,
    this.address,
    this.taxOffice,
    this.taxNumber,
    this.defaultPriceMode,
    required this.defaultDiscountRate,
    required this.riskLimit,
    required this.paymentTermDays,
    required this.isActive,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['code'] = Variable<String>(code);
    map['title'] = Variable<String>(title);
    map['title_normalized'] = Variable<String>(titleNormalized);
    if (!nullToAbsent || contactPerson != null) {
      map['contact_person'] = Variable<String>(contactPerson);
    }
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || address != null) {
      map['address'] = Variable<String>(address);
    }
    if (!nullToAbsent || taxOffice != null) {
      map['tax_office'] = Variable<String>(taxOffice);
    }
    if (!nullToAbsent || taxNumber != null) {
      map['tax_number'] = Variable<String>(taxNumber);
    }
    if (!nullToAbsent || defaultPriceMode != null) {
      map['default_price_mode'] = Variable<String>(defaultPriceMode);
    }
    {
      map['default_discount_rate'] = Variable<int>(
        $CustomersTable.$converterdefaultDiscountRate.toSql(
          defaultDiscountRate,
        ),
      );
    }
    {
      map['risk_limit'] = Variable<int>(
        $CustomersTable.$converterriskLimit.toSql(riskLimit),
      );
    }
    map['payment_term_days'] = Variable<int>(paymentTermDays);
    map['is_active'] = Variable<bool>(isActive);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  CustomersCompanion toCompanion(bool nullToAbsent) {
    return CustomersCompanion(
      id: Value(id),
      code: Value(code),
      title: Value(title),
      titleNormalized: Value(titleNormalized),
      contactPerson: contactPerson == null && nullToAbsent
          ? const Value.absent()
          : Value(contactPerson),
      phone: phone == null && nullToAbsent
          ? const Value.absent()
          : Value(phone),
      email: email == null && nullToAbsent
          ? const Value.absent()
          : Value(email),
      address: address == null && nullToAbsent
          ? const Value.absent()
          : Value(address),
      taxOffice: taxOffice == null && nullToAbsent
          ? const Value.absent()
          : Value(taxOffice),
      taxNumber: taxNumber == null && nullToAbsent
          ? const Value.absent()
          : Value(taxNumber),
      defaultPriceMode: defaultPriceMode == null && nullToAbsent
          ? const Value.absent()
          : Value(defaultPriceMode),
      defaultDiscountRate: Value(defaultDiscountRate),
      riskLimit: Value(riskLimit),
      paymentTermDays: Value(paymentTermDays),
      isActive: Value(isActive),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
    );
  }

  factory Customer.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Customer(
      id: serializer.fromJson<String>(json['id']),
      code: serializer.fromJson<String>(json['code']),
      title: serializer.fromJson<String>(json['title']),
      titleNormalized: serializer.fromJson<String>(json['titleNormalized']),
      contactPerson: serializer.fromJson<String?>(json['contactPerson']),
      phone: serializer.fromJson<String?>(json['phone']),
      email: serializer.fromJson<String?>(json['email']),
      address: serializer.fromJson<String?>(json['address']),
      taxOffice: serializer.fromJson<String?>(json['taxOffice']),
      taxNumber: serializer.fromJson<String?>(json['taxNumber']),
      defaultPriceMode: serializer.fromJson<String?>(json['defaultPriceMode']),
      defaultDiscountRate: serializer.fromJson<Rate>(
        json['defaultDiscountRate'],
      ),
      riskLimit: serializer.fromJson<Money>(json['riskLimit']),
      paymentTermDays: serializer.fromJson<int>(json['paymentTermDays']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      note: serializer.fromJson<String?>(json['note']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'code': serializer.toJson<String>(code),
      'title': serializer.toJson<String>(title),
      'titleNormalized': serializer.toJson<String>(titleNormalized),
      'contactPerson': serializer.toJson<String?>(contactPerson),
      'phone': serializer.toJson<String?>(phone),
      'email': serializer.toJson<String?>(email),
      'address': serializer.toJson<String?>(address),
      'taxOffice': serializer.toJson<String?>(taxOffice),
      'taxNumber': serializer.toJson<String?>(taxNumber),
      'defaultPriceMode': serializer.toJson<String?>(defaultPriceMode),
      'defaultDiscountRate': serializer.toJson<Rate>(defaultDiscountRate),
      'riskLimit': serializer.toJson<Money>(riskLimit),
      'paymentTermDays': serializer.toJson<int>(paymentTermDays),
      'isActive': serializer.toJson<bool>(isActive),
      'note': serializer.toJson<String?>(note),
    };
  }

  Customer copyWith({
    String? id,
    String? code,
    String? title,
    String? titleNormalized,
    Value<String?> contactPerson = const Value.absent(),
    Value<String?> phone = const Value.absent(),
    Value<String?> email = const Value.absent(),
    Value<String?> address = const Value.absent(),
    Value<String?> taxOffice = const Value.absent(),
    Value<String?> taxNumber = const Value.absent(),
    Value<String?> defaultPriceMode = const Value.absent(),
    Rate? defaultDiscountRate,
    Money? riskLimit,
    int? paymentTermDays,
    bool? isActive,
    Value<String?> note = const Value.absent(),
  }) => Customer(
    id: id ?? this.id,
    code: code ?? this.code,
    title: title ?? this.title,
    titleNormalized: titleNormalized ?? this.titleNormalized,
    contactPerson: contactPerson.present
        ? contactPerson.value
        : this.contactPerson,
    phone: phone.present ? phone.value : this.phone,
    email: email.present ? email.value : this.email,
    address: address.present ? address.value : this.address,
    taxOffice: taxOffice.present ? taxOffice.value : this.taxOffice,
    taxNumber: taxNumber.present ? taxNumber.value : this.taxNumber,
    defaultPriceMode: defaultPriceMode.present
        ? defaultPriceMode.value
        : this.defaultPriceMode,
    defaultDiscountRate: defaultDiscountRate ?? this.defaultDiscountRate,
    riskLimit: riskLimit ?? this.riskLimit,
    paymentTermDays: paymentTermDays ?? this.paymentTermDays,
    isActive: isActive ?? this.isActive,
    note: note.present ? note.value : this.note,
  );
  Customer copyWithCompanion(CustomersCompanion data) {
    return Customer(
      id: data.id.present ? data.id.value : this.id,
      code: data.code.present ? data.code.value : this.code,
      title: data.title.present ? data.title.value : this.title,
      titleNormalized: data.titleNormalized.present
          ? data.titleNormalized.value
          : this.titleNormalized,
      contactPerson: data.contactPerson.present
          ? data.contactPerson.value
          : this.contactPerson,
      phone: data.phone.present ? data.phone.value : this.phone,
      email: data.email.present ? data.email.value : this.email,
      address: data.address.present ? data.address.value : this.address,
      taxOffice: data.taxOffice.present ? data.taxOffice.value : this.taxOffice,
      taxNumber: data.taxNumber.present ? data.taxNumber.value : this.taxNumber,
      defaultPriceMode: data.defaultPriceMode.present
          ? data.defaultPriceMode.value
          : this.defaultPriceMode,
      defaultDiscountRate: data.defaultDiscountRate.present
          ? data.defaultDiscountRate.value
          : this.defaultDiscountRate,
      riskLimit: data.riskLimit.present ? data.riskLimit.value : this.riskLimit,
      paymentTermDays: data.paymentTermDays.present
          ? data.paymentTermDays.value
          : this.paymentTermDays,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      note: data.note.present ? data.note.value : this.note,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Customer(')
          ..write('id: $id, ')
          ..write('code: $code, ')
          ..write('title: $title, ')
          ..write('titleNormalized: $titleNormalized, ')
          ..write('contactPerson: $contactPerson, ')
          ..write('phone: $phone, ')
