  final String id;
  final String docNo;
  final String customerId;
  final String? salesQuoteId;
  final int docDate;
  final int? dueDate;
  final PriceMode priceMode;
  final String? invoiceNo;
  final String? waybillNo;
  final Money subtotalNet;
  final Money vatTotal;
  final Money grandTotal;

