      );
    }
    if (!nullToAbsent || priceListId != null) {
      map['price_list_id'] = Variable<String>(priceListId);
    }
    {
      map['list_price_m3'] = Variable<int>(
        $SaleItemsTable.$converterlistPriceM3.toSql(listPriceM3),
