        $SaleItemsTable.$converterunitPriceM3.toSql(unitPriceM3),
      );
    }
    {
      map['net_total'] = Variable<int>(
        $SaleItemsTable.$converternetTotal.toSql(netTotal),
      );
    }
    {
      map['vat_rate'] = Variable<int>(
        $SaleItemsTable.$convertervatRate.toSql(vatRate),
