class Instrument extends DataClass implements Insertable<Instrument> {
  final String id;
  final String kind;
  final String direction;
  final String? serialNo;
  final String? bankName;
  final String? branch;

  /// Keşideci veya borçlu.
  final String? drawerName;
  final int dueDate;
  final Money amount;
  final String? customerId;
  final String? supplierId;
  final String? endorsedToSupplierId;

  /// ÖNBELLEK — doğrusu instrument_events zincirinin sonucudur.
  final String currentStatus;
  final String? sourceType;
  final String? sourceId;
  final int createdAt;
  final String? note;
  const Instrument({
    required this.id,
    required this.kind,
    required this.direction,
    this.serialNo,
    this.bankName,
    this.branch,
    this.drawerName,
    required this.dueDate,
    required this.amount,
    this.customerId,
    this.supplierId,
    this.endorsedToSupplierId,
    required this.currentStatus,
    this.sourceType,
    this.sourceId,
    required this.createdAt,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['kind'] = Variable<String>(kind);
    map['direction'] = Variable<String>(direction);
    if (!nullToAbsent || serialNo != null) {
      map['serial_no'] = Variable<String>(serialNo);
    }
    if (!nullToAbsent || bankName != null) {
      map['bank_name'] = Variable<String>(bankName);
    }
    if (!nullToAbsent || branch != null) {
      map['branch'] = Variable<String>(branch);
    }
    if (!nullToAbsent || drawerName != null) {
      map['drawer_name'] = Variable<String>(drawerName);
    }
    map['due_date'] = Variable<int>(dueDate);
    {
      map['amount'] = Variable<int>(
        $InstrumentsTable.$converteramount.toSql(amount),
      );
    }
    if (!nullToAbsent || customerId != null) {
      map['customer_id'] = Variable<String>(customerId);
    }
    if (!nullToAbsent || supplierId != null) {
      map['supplier_id'] = Variable<String>(supplierId);
    }
    if (!nullToAbsent || endorsedToSupplierId != null) {
      map['endorsed_to_supplier_id'] = Variable<String>(endorsedToSupplierId);
    }
    map['current_status'] = Variable<String>(currentStatus);
    if (!nullToAbsent || sourceType != null) {
      map['source_type'] = Variable<String>(sourceType);
    }
    if (!nullToAbsent || sourceId != null) {
      map['source_id'] = Variable<String>(sourceId);
    }
    map['created_at'] = Variable<int>(createdAt);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  InstrumentsCompanion toCompanion(bool nullToAbsent) {
    return InstrumentsCompanion(
      id: Value(id),
      kind: Value(kind),
      direction: Value(direction),
      serialNo: serialNo == null && nullToAbsent
          ? const Value.absent()
          : Value(serialNo),
      bankName: bankName == null && nullToAbsent
          ? const Value.absent()
          : Value(bankName),
      branch: branch == null && nullToAbsent
          ? const Value.absent()
          : Value(branch),
      drawerName: drawerName == null && nullToAbsent
          ? const Value.absent()
          : Value(drawerName),
      dueDate: Value(dueDate),
      amount: Value(amount),
      customerId: customerId == null && nullToAbsent
          ? const Value.absent()
          : Value(customerId),
      supplierId: supplierId == null && nullToAbsent
          ? const Value.absent()
          : Value(supplierId),
      endorsedToSupplierId: endorsedToSupplierId == null && nullToAbsent
          ? const Value.absent()
          : Value(endorsedToSupplierId),
      currentStatus: Value(currentStatus),
      sourceType: sourceType == null && nullToAbsent
          ? const Value.absent()
          : Value(sourceType),
      sourceId: sourceId == null && nullToAbsent
          ? const Value.absent()
          : Value(sourceId),
      createdAt: Value(createdAt),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
    );
  }

  factory Instrument.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Instrument(
      id: serializer.fromJson<String>(json['id']),
      kind: serializer.fromJson<String>(json['kind']),
      direction: serializer.fromJson<String>(json['direction']),
      serialNo: serializer.fromJson<String?>(json['serialNo']),
      bankName: serializer.fromJson<String?>(json['bankName']),
      branch: serializer.fromJson<String?>(json['branch']),
      drawerName: serializer.fromJson<String?>(json['drawerName']),
      dueDate: serializer.fromJson<int>(json['dueDate']),
      amount: serializer.fromJson<Money>(json['amount']),
      customerId: serializer.fromJson<String?>(json['customerId']),
      supplierId: serializer.fromJson<String?>(json['supplierId']),
      endorsedToSupplierId: serializer.fromJson<String?>(
        json['endorsedToSupplierId'],
      ),
      currentStatus: serializer.fromJson<String>(json['currentStatus']),
      sourceType: serializer.fromJson<String?>(json['sourceType']),
      sourceId: serializer.fromJson<String?>(json['sourceId']),
      createdAt: serializer.fromJson<int>(json['createdAt']),
      note: serializer.fromJson<String?>(json['note']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'kind': serializer.toJson<String>(kind),
      'direction': serializer.toJson<String>(direction),
      'serialNo': serializer.toJson<String?>(serialNo),
      'bankName': serializer.toJson<String?>(bankName),
      'branch': serializer.toJson<String?>(branch),
      'drawerName': serializer.toJson<String?>(drawerName),
      'dueDate': serializer.toJson<int>(dueDate),
      'amount': serializer.toJson<Money>(amount),
      'customerId': serializer.toJson<String?>(customerId),
      'supplierId': serializer.toJson<String?>(supplierId),
      'endorsedToSupplierId': serializer.toJson<String?>(endorsedToSupplierId),
      'currentStatus': serializer.toJson<String>(currentStatus),
      'sourceType': serializer.toJson<String?>(sourceType),
      'sourceId': serializer.toJson<String?>(sourceId),
      'createdAt': serializer.toJson<int>(createdAt),
      'note': serializer.toJson<String?>(note),
    };
  }

  Instrument copyWith({
    String? id,
    String? kind,
    String? direction,
    Value<String?> serialNo = const Value.absent(),
    Value<String?> bankName = const Value.absent(),
    Value<String?> branch = const Value.absent(),
    Value<String?> drawerName = const Value.absent(),
    int? dueDate,
    Money? amount,
    Value<String?> customerId = const Value.absent(),
    Value<String?> supplierId = const Value.absent(),
    Value<String?> endorsedToSupplierId = const Value.absent(),
    String? currentStatus,
    Value<String?> sourceType = const Value.absent(),
    Value<String?> sourceId = const Value.absent(),
    int? createdAt,
    Value<String?> note = const Value.absent(),
  }) => Instrument(
    id: id ?? this.id,
    kind: kind ?? this.kind,
    direction: direction ?? this.direction,
    serialNo: serialNo.present ? serialNo.value : this.serialNo,
    bankName: bankName.present ? bankName.value : this.bankName,
    branch: branch.present ? branch.value : this.branch,
    drawerName: drawerName.present ? drawerName.value : this.drawerName,
    dueDate: dueDate ?? this.dueDate,
    amount: amount ?? this.amount,
    customerId: customerId.present ? customerId.value : this.customerId,
    supplierId: supplierId.present ? supplierId.value : this.supplierId,
    endorsedToSupplierId: endorsedToSupplierId.present
        ? endorsedToSupplierId.value
        : this.endorsedToSupplierId,
    currentStatus: currentStatus ?? this.currentStatus,
    sourceType: sourceType.present ? sourceType.value : this.sourceType,
    sourceId: sourceId.present ? sourceId.value : this.sourceId,
    createdAt: createdAt ?? this.createdAt,
    note: note.present ? note.value : this.note,
  );
  Instrument copyWithCompanion(InstrumentsCompanion data) {
    return Instrument(
      id: data.id.present ? data.id.value : this.id,
      kind: data.kind.present ? data.kind.value : this.kind,
      direction: data.direction.present ? data.direction.value : this.direction,
      serialNo: data.serialNo.present ? data.serialNo.value : this.serialNo,
      bankName: data.bankName.present ? data.bankName.value : this.bankName,
      branch: data.branch.present ? data.branch.value : this.branch,
      drawerName: data.drawerName.present
          ? data.drawerName.value
          : this.drawerName,
      dueDate: data.dueDate.present ? data.dueDate.value : this.dueDate,
      amount: data.amount.present ? data.amount.value : this.amount,
      customerId: data.customerId.present
          ? data.customerId.value
          : this.customerId,
      supplierId: data.supplierId.present
          ? data.supplierId.value
          : this.supplierId,
      endorsedToSupplierId: data.endorsedToSupplierId.present
          ? data.endorsedToSupplierId.value
          : this.endorsedToSupplierId,
      currentStatus: data.currentStatus.present
          ? data.currentStatus.value
          : this.currentStatus,
      sourceType: data.sourceType.present
          ? data.sourceType.value
          : this.sourceType,
      sourceId: data.sourceId.present ? data.sourceId.value : this.sourceId,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      note: data.note.present ? data.note.value : this.note,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Instrument(')
          ..write('id: $id, ')
          ..write('kind: $kind, ')
          ..write('direction: $direction, ')
          ..write('serialNo: $serialNo, ')
          ..write('bankName: $bankName, ')
          ..write('branch: $branch, ')
          ..write('drawerName: $drawerName, ')
          ..write('dueDate: $dueDate, ')
          ..write('amount: $amount, ')
          ..write('customerId: $customerId, ')
          ..write('supplierId: $supplierId, ')
          ..write('endorsedToSupplierId: $endorsedToSupplierId, ')
          ..write('currentStatus: $currentStatus, ')
          ..write('sourceType: $sourceType, ')
          ..write('sourceId: $sourceId, ')
          ..write('createdAt: $createdAt, ')
          ..write('note: $note')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    kind,
    direction,
    serialNo,
    bankName,
    branch,
    drawerName,
    dueDate,
    amount,
    customerId,
    supplierId,
    endorsedToSupplierId,
    currentStatus,
    sourceType,
    sourceId,
    createdAt,
    note,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Instrument &&
          other.id == this.id &&
          other.kind == this.kind &&
          other.direction == this.direction &&
          other.serialNo == this.serialNo &&
          other.bankName == this.bankName &&
          other.branch == this.branch &&
          other.drawerName == this.drawerName &&
          other.dueDate == this.dueDate &&
          other.amount == this.amount &&
          other.customerId == this.customerId &&
          other.supplierId == this.supplierId &&
          other.endorsedToSupplierId == this.endorsedToSupplierId &&
          other.currentStatus == this.currentStatus &&
          other.sourceType == this.sourceType &&
          other.sourceId == this.sourceId &&
          other.createdAt == this.createdAt &&
          other.note == this.note);
