class CuttingOrder extends DataClass implements Insertable<CuttingOrder> {
  final String id;
  final String docNo;

  /// type = KESIMHANE olan tedarikçi.
  final String cutterSupplierId;
  final String? salesQuoteId;
  final String? customerId;
  final int sentDate;
  final int? expectedReturnDate;
  final String status;

  /// KDV hariç — maliyete böyle girer; cariye brüt yazılır.
  final Money cuttingFeeNet;
  final Rate cuttingFeeVatRate;
  final Money freightNet;
  final Volume sourceVolumeTotal;
  final Volume resultVolumeTotal;

  /// Kesim firesi = kaynak − hedef. Ayrı maliyet yazılmaz (BRIEF §5.3).
  final Volume wasteVolume;
  final String? commandId;
  final int createdAt;
  final String? note;
  const CuttingOrder({
    required this.id,
    required this.docNo,
    required this.cutterSupplierId,
    this.salesQuoteId,
    this.customerId,
    required this.sentDate,
    this.expectedReturnDate,
    required this.status,
    required this.cuttingFeeNet,
    required this.cuttingFeeVatRate,
    required this.freightNet,
    required this.sourceVolumeTotal,
    required this.resultVolumeTotal,
    required this.wasteVolume,
    this.commandId,
    required this.createdAt,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['doc_no'] = Variable<String>(docNo);
    map['cutter_supplier_id'] = Variable<String>(cutterSupplierId);
    if (!nullToAbsent || salesQuoteId != null) {
      map['sales_quote_id'] = Variable<String>(salesQuoteId);
    }
    if (!nullToAbsent || customerId != null) {
      map['customer_id'] = Variable<String>(customerId);
    }
    map['sent_date'] = Variable<int>(sentDate);
    if (!nullToAbsent || expectedReturnDate != null) {
      map['expected_return_date'] = Variable<int>(expectedReturnDate);
    }
    map['status'] = Variable<String>(status);
    {
      map['cutting_fee_net'] = Variable<int>(
        $CuttingOrdersTable.$convertercuttingFeeNet.toSql(cuttingFeeNet),
      );
    }
    {
      map['cutting_fee_vat_rate'] = Variable<int>(
        $CuttingOrdersTable.$convertercuttingFeeVatRate.toSql(
          cuttingFeeVatRate,
        ),
      );
    }
    {
      map['freight_net'] = Variable<int>(
        $CuttingOrdersTable.$converterfreightNet.toSql(freightNet),
      );
    }
    {
      map['source_volume_total'] = Variable<int>(
        $CuttingOrdersTable.$convertersourceVolumeTotal.toSql(
          sourceVolumeTotal,
        ),
      );
    }
    {
      map['result_volume_total'] = Variable<int>(
